const dialog=document.getElementById('project-dialog');
const dialogTitle=document.getElementById('dialog-title');
const dialogCategory=document.getElementById('dialog-category');
const dialogDescription=document.getElementById('dialog-description');
const dialogImages=document.getElementById('dialog-images');
const dialogCredit=document.getElementById('dialog-credit');
const dialogSource=document.getElementById('dialog-source');
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const projectOrder=['warrior','summer','tiger','kshatriya','arttoy','autumn','angel','snake','mavia','maviamini','blockclans'];
let currentProject;
let projectTrigger;
const imagePath=num=>typeof num==='number'?`assets/portfolio-${String(num).padStart(2,'0')}.webp`:`assets/${num}`;
const projectNav=document.createElement('nav');
projectNav.className='project-pagination';
projectNav.setAttribute('aria-label','Explore more projects');
const previousProject=document.createElement('a');
const nextProject=document.createElement('a');
projectNav.append(previousProject,nextProject);
dialog.append(projectNav);
const mediaToolbar=document.createElement('div');mediaToolbar.className='project-media-toolbar';
const motionJump=document.createElement('button');motionJump.type='button';motionJump.className='text-link';
mediaToolbar.append(motionJump);dialogImages.before(mediaToolbar);
function renderProject(key,trigger){
  window.PortfolioMedia?.disposeScene();
  window.PortfolioMedia?.pausePreviews();
  const project=projects[key];
  if(!project)return;
  dialogImages.querySelectorAll('video').forEach(video=>video.pause());
  currentProject=key;
  if(trigger)projectTrigger=trigger;
  dialogTitle.textContent=project.title;
  dialogCategory.textContent=project.category.toLowerCase().replace(/(^|\/ )\w/g,c=>c.toUpperCase()).replace(/\b3d\b/gi,'3D');
  dialogDescription.textContent=project.description;
  dialogCredit.textContent=project.credit;
  mediaToolbar.hidden=!project.videos?.length;
  motionJump.textContent=project.videos?.length===1?'WATCH VIDEO ↓':`${String(project.videos?.length||0).padStart(2,'0')} VIDEOS ↓`;
  motionJump.onclick=()=>dialogImages.querySelector('.project-motion')?.scrollIntoView({behavior:reducedMotion.matches?'auto':'smooth',block:'start'});
  dialogSource.hidden=!project.source;
  if(project.source){dialogSource.href=project.source;dialogSource.textContent=project.sourceLabel||'VIEW ORIGINAL PROJECT ↗';}else{dialogSource.removeAttribute('href');}
  dialogImages.replaceChildren(...project.images.map((num,index)=>{
    const frame=document.createElement('button');
    frame.type='button';
    frame.className='artwork-frame';
    frame.setAttribute('aria-label',`Enlarge ${project.title}, image ${index+1}`);
    const img=document.createElement('img');
    img.src=imagePath(num);
    img.alt=`${project.title} — ${index===0?'finished artwork':'additional artwork and production presentation '+index}`;
    const size=typeof num==='number'?[2400,1350]:(imageSizes[num]||[1800,1800]);
    [img.width,img.height]=size;
    if(size[1]>size[0]*1.45)frame.classList.add('portrait-artwork');
    if(index>0)img.loading='lazy';
    const hint=document.createElement('span');
    hint.className='artwork-hint';
    hint.setAttribute('aria-hidden','true');
    hint.textContent='VIEW FULL SIZE ↗';
    frame.append(img,hint);
    frame.addEventListener('click',()=>openImage(index));
    return frame;
  }));
  if(project.videos?.length){
    const section=document.createElement('section');
    section.className='project-motion';section.setAttribute('aria-label',`${project.title} videos`);
    const heading=document.createElement('h3');heading.textContent='IN MOTION';section.append(heading);
    project.videos.forEach(clip=>section.append(window.PortfolioMedia.makePreview(clip)));
    dialogImages.append(section);
  }
  if(project.viewer)dialogImages.append(window.PortfolioMedia.makeScene(project));
  const position=projectOrder.indexOf(key);
  const previous=projectOrder[(position-1+projectOrder.length)%projectOrder.length];
  const next=projectOrder[(position+1)%projectOrder.length];
  previousProject.textContent=`← PREVIOUS / ${projects[previous].title}`;
  nextProject.textContent=`NEXT / ${projects[next].title} →`;
  previousProject.href=projectHref(previous);nextProject.href=projectHref(next);
  previousProject.onclick=event=>{if(isPlainProjectClick(event)){event.preventDefault();openProject(previous);}};
  nextProject.onclick=event=>{if(isPlainProjectClick(event)){event.preventDefault();openProject(next);}};
  window.PortfolioProjectExperience?.update(key,{previous,next});
  if(!dialog.open)dialog.showModal();
  dialog.scrollTop=0;
  document.body.style.overflow='hidden';
  document.body.classList.add('project-dialog-open');
  document.dispatchEvent(new Event('portfolio:projectchange'));
  document.querySelector('.dialog-close').focus({preventScroll:true});
}
document.querySelectorAll('[data-project]').forEach(link=>link.addEventListener('click',event=>{if(isPlainProjectClick(event)){event.preventDefault();openProject(link.dataset.project,link);}}));
document.querySelector('.dialog-close').addEventListener('click',()=>closeProject());
dialog.addEventListener('cancel',event=>{event.preventDefault();closeProject();});
dialog.addEventListener('close',()=>{if(dialog.open)return;window.PortfolioProjectExperience?.dispose();window.PortfolioMedia?.disposeScene();window.PortfolioMedia?.pausePreviews();dialogImages.querySelectorAll('video').forEach(video=>video.pause());document.body.style.overflow='';document.body.classList.remove('project-dialog-open');document.dispatchEvent(new Event('portfolio:projectchange'));projectTrigger?.focus({preventScroll:true});});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closeProject();}});
let toastTimeout;
document.getElementById('copy-email').addEventListener('click',async()=>{
  try{await navigator.clipboard.writeText('hhiep.work@gmail.com');const toast=document.getElementById('toast');toast.textContent='Email copied to clipboard';toast.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.classList.remove('visible'),2500);}catch{window.location.href='mailto:hhiep.work@gmail.com';}
});

// Native nested dialog keeps keyboard focus inside the full-size image viewer.
const viewer=document.getElementById('image-viewer');
const viewerImage=document.getElementById('viewer-image');
const viewerCaption=document.getElementById('viewer-caption');
let imageIndex=0;
let imageTrigger;
function showImage(index){
  const project=projects[currentProject];
  imageIndex=(index+project.images.length)%project.images.length;
  viewerImage.src=imagePath(project.images[imageIndex]);
  viewerImage.alt=`${project.title} — artwork ${imageIndex+1}`;
  viewerCaption.textContent=`${project.title} / ${String(imageIndex+1).padStart(2,'0')} — ${String(project.images.length).padStart(2,'0')}`;
  document.getElementById('viewer-prev').disabled=project.images.length<2;
  document.getElementById('viewer-next').disabled=project.images.length<2;
}
function openImage(index){
  window.PortfolioMedia?.pausePreviews();
  imageTrigger=document.activeElement;
  showImage(index);
  viewer.showModal();
  document.querySelector('.viewer-close').focus({preventScroll:true});
}
document.querySelector('.viewer-close').addEventListener('click',()=>viewer.close());
document.getElementById('viewer-prev').addEventListener('click',()=>showImage(imageIndex-1));
document.getElementById('viewer-next').addEventListener('click',()=>showImage(imageIndex+1));
viewer.addEventListener('close',()=>{viewerImage.removeAttribute('src');imageTrigger?.focus({preventScroll:true});});
viewer.addEventListener('keydown',event=>{
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){
    event.preventDefault();showImage(imageIndex+(event.key==='ArrowLeft'?-1:1));
  }
});
let swipeStart;
viewer.addEventListener('touchstart',event=>{if(event.touches.length===1)swipeStart={x:event.touches[0].clientX,y:event.touches[0].clientY};else swipeStart=null;},{passive:true});
viewer.addEventListener('touchend',event=>{
  if(!swipeStart)return;
  const dx=event.changedTouches[0].clientX-swipeStart.x;
  const dy=event.changedTouches[0].clientY-swipeStart.y;
  if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)showImage(imageIndex+(dx<0?1:-1));
  swipeStart=null;
},{passive:true});
viewer.addEventListener('touchcancel',()=>{swipeStart=null;},{passive:true});

// Start visible: content stays readable if scripting or observation is unavailable.
if('IntersectionObserver' in window){
  const observer=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(!entry.isIntersecting)return;
      if(!reducedMotion.matches){
        entry.target.animate([{opacity:.35,transform:'translateY(24px)'},{opacity:1,transform:'translateY(0)'}],{duration:800,easing:'cubic-bezier(.22,1,.36,1)'});
      }
      observer.unobserve(entry.target);
    });
  },{threshold:.08});
  document.querySelectorAll('.project-card,.production-card,.section-heading-row,.about-layout').forEach(element=>observer.observe(element));
}

// Carry the selected artwork into the project; respect reduced-motion preferences.
let activeTransition;
let transitionVersion=0;
function artworkTransition(from,update,to){
  const version=++transitionVersion;
  activeTransition?.skipTransition();
  document.querySelectorAll('[data-transition-art]').forEach(el=>{el.style.viewTransitionName='';el.removeAttribute('data-transition-art');});
  if(!document.startViewTransition||reducedMotion.matches){activeTransition=null;update();return;}
  if(from){from.style.viewTransitionName='project-art';from.dataset.transitionArt='';}
  activeTransition=document.startViewTransition(()=>{
    if(version!==transitionVersion)return;
    if(from){from.style.viewTransitionName='';from.removeAttribute('data-transition-art');}
    update();
    const target=to();
    if(target){target.style.viewTransitionName='project-art';target.dataset.transitionArt='';}
  });
  const thisTransition=activeTransition;
  // Resizing or choosing reduced motion can cancel the visual transition normally.
  thisTransition.ready.catch(()=>{});
  thisTransition.finished.catch(()=>{}).finally(()=>{
    if(activeTransition!==thisTransition)return;
    document.querySelectorAll('[data-transition-art]').forEach(el=>{el.style.viewTransitionName='';el.removeAttribute('data-transition-art');});
    activeTransition=null;
  });
}
function showProject(key,trigger){
  const from=dialog.open?dialogImages.querySelector('.artwork-frame img'):document.querySelector(`.project-image[data-project="${key}"] img`);
  artworkTransition(from,()=>renderProject(key,trigger),()=>dialogImages.querySelector('.artwork-frame img'));
}
function hideProject({reveal=false}={}){
  if(!dialog.open)return;
  const key=currentProject;
  artworkTransition(dialogImages.querySelector('.artwork-frame img'),()=>{
    dialog.close();
    if(reveal)document.querySelector(`.project-image[data-project="${key}"]`)?.scrollIntoView({block:'center',behavior:'instant'});
  },()=>document.querySelector(`.project-image[data-project="${key}"] img`));
}
window.addEventListener('resize',()=>activeTransition?.skipTransition(),{passive:true});
reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches)activeTransition?.skipTransition();});
